using System;
using LinearAlgebra;
using LinearAlgebra.Sparse;
using NUnit.Framework;
using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;
using Unity.Mathematics;

// Block ILU(0) preconditioner (floatILU0) + right-preconditioned BiCGSTAB (Krylov.biCGStab).
// Anchors: (a) on a block-tridiagonal (fill-free) NONSYMMETRIC system ILU(0) is the exact LU,
// so Apply must match a dense LU solve; (b) biCGStab with ILU(0) converges to the true
// solution and needs fewer iterations than unpreconditioned biCGStab on the same system.
public class floatSparseILU0Tests
{
    [BurstCompile(CompileSynchronously = true)]
    public struct SparseILU0TestJob : IJob
    {
        public enum TestType
        {
            ExactOnBlockTridiagonal,
            PbiCGStabConvergesAndBeatsPlain,
        }

        public TestType Type;

        static float Tol() => 1e-3f;

        public void Execute()
        {
            switch (Type)
            {
                case TestType.ExactOnBlockTridiagonal: ExactOnBlockTridiagonal(); break;
                case TestType.PbiCGStabConvergesAndBeatsPlain: PbiCGStabConvergesAndBeatsPlain(); break;
            }
        }

        // Diagonally dominant NONSYMMETRIC block-tridiagonal system (fill-free pattern).
        static floatBSR BuildNonsymTridiag(ref Arena arena, int nb, int BR, uint seed)
        {
            var builder = arena.floatBSRBuilder(nb, nb, BR, BR);
            var rng = new Unity.Mathematics.Random(seed);
            var blk = arena.floatMat(BR, BR);

            for (int i = 0; i < nb; i++)
            {
                for (int r = 0; r < BR; r++)
                    for (int c = 0; c < BR; c++)
                        blk[r, c] = (r == c ? (float)(4 * BR) : (float)0) + (float)rng.NextFloat(-0.5f, 0.5f);
                builder.AddBlock(i, i, in blk);

                if (i + 1 < nb)
                {
                    for (int r = 0; r < BR; r++)
                        for (int c = 0; c < BR; c++)
                            blk[r, c] = (float)rng.NextFloat(-0.6f, 0.6f);
                    builder.AddBlock(i + 1, i, in blk);

                    for (int r = 0; r < BR; r++)
                        for (int c = 0; c < BR; c++)
                            blk[r, c] = (float)rng.NextFloat(-0.6f, 0.6f);   // NOT the transpose
                    builder.AddBlock(i, i + 1, in blk);
                }
            }
            return builder.ToBSR(ref arena);
        }

        void ExactOnBlockTridiagonal()
        {
            var arena = new Arena(Allocator.Persistent);

            const int nb = 6, BR = 3;
            var A = BuildNonsymTridiag(ref arena, nb, BR, 841001u);
            int n = A.M_Rows;

            var M = arena.floatILU0(in A);
            Assert.IsTrue(M.Shift == (float)0);

            var r = arena.floatRandomVec(n, -1f, 1f, 841002u);
            var z = arena.floatVec(n);
            M.Apply(in r, ref z);

            // Dense LU oracle: on a fill-free pattern ILU(0) is exact, so z == A^-1 r.
            var D = A.ToDense(ref arena);
            var zRef = arena.floatVec(n);
            for (int i = 0; i < n; i++) zRef[i] = r[i];
            var P = new Pivot(n, Allocator.Temp);
            var info = LU.solveInPlace(ref D, ref P, ref zRef);
            Assert.IsTrue(info.Solved);

            for (int i = 0; i < n; i++)
                Assert.IsTrue(math.abs(z[i] - zRef[i]) < Tol() * ((float)1 + math.abs(zRef[i])));

            arena.Dispose();
        }

        void PbiCGStabConvergesAndBeatsPlain()
        {
            var arena = new Arena(Allocator.Persistent);

            const int nb = 40, BR = 3;
            var A = BuildNonsymTridiag(ref arena, nb, BR, 841003u);
            int n = A.M_Rows;

            var xTrue = arena.floatRandomVec(n, 0.5f, 1.5f, 841004u);
            var b = BSR.spMV(in A, in xTrue);
            float tol = Consts.floatSqrtEps;
            int maxIter = 4 * n;

            // Plain BiCGSTAB baseline.
            var xP = arena.floatVec(n);
            var rP = arena.floatVec(n); var rh = arena.floatVec(n); var pP = arena.floatVec(n);
            var vP = arena.floatVec(n); var tP = arena.floatVec(n);
            var op = new floatBSROperator(in A);
            var infoPlain = Krylov.biCGStab(in op, in b, ref xP, ref rP, ref rh, ref pP, ref vP, ref tP, maxIter, tol);
            Assert.IsTrue(infoPlain.Solved);

            // ILU(0)-preconditioned.
            var M = arena.floatILU0(in A);
            var xI = arena.floatVec(n);
            var infoIlu = Krylov.biCGStab(in A, in M, in b, ref xI, maxIter, tol);
            Assert.IsTrue(infoIlu.Solved);
            Assert.IsTrue((double)infoIlu.iterations <= (double)infoPlain.iterations * 0.9);

            for (int i = 0; i < n; i++)
                Assert.IsTrue(math.abs(xI[i] - xTrue[i]) < Tol() * ((float)1 + math.abs(xTrue[i])));

            arena.Dispose();
        }
    }

    [Test]
    public void ExactOnBlockTridiagonalTest()
        => new SparseILU0TestJob { Type = SparseILU0TestJob.TestType.ExactOnBlockTridiagonal }.Run();

    [Test]
    public void PbiCGStabConvergesAndBeatsPlainTest()
        => new SparseILU0TestJob { Type = SparseILU0TestJob.TestType.PbiCGStabConvergesAndBeatsPlain }.Run();

    [Test]
    public void MissingDiagonalThrows()
    {
        var arena = new Arena(Allocator.Persistent);
        try
        {
            var builder = arena.floatBSRBuilder(2, 2, 2, 2);
            var block = arena.floatMat(2, 2, (float)1);
            builder.AddBlock(0, 0, in block);
            builder.AddBlock(1, 0, in block);
            var A = builder.ToBSR(ref arena);
            Assert.Throws<ArgumentException>(() => { var m = arena.floatILU0(in A); });
        }
        finally { arena.Dispose(); }
    }
}
